/* Drags each linked car to follow the train after it moved, then flags the coupling moby; with no cars it reports and deletes the train.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l03/gameplay/entities/00292578.c, FUN_L03_00292d10. */
void update_metropolis_train_idle_motion(struct Moby *moby) {
    float old_pos[4];
    float old_rot[4];
    float delta[4];
    struct Train292890 *data;
    Moby *car;
    Car292890 *car_data;
    char *p;
    char *q;
    int next_id;
    int id;
    float *dp;
    char *motion;

    data = (struct Train292890 *)moby->pvars;
    moby->unk72 = 0x40;
    p = &moby->pos;
    qcopy(old_pos, p);
    q = &moby->rot;
    qcopy(old_rot, q);
    next_id = data->iA0;
    if (next_id != -1) {
        id = next_id;
        dp = delta;
        motion = (char *)data->motion;
        do {
            car = (Moby *)(kerwan_mobys_t + (id << 8));
            car_data = (Car292890 *)car->pvars;
            car->unk72 = 0x40;
            FastVecSub_r(delta, &car->pos, car_data->prev_pos);
            update_entity_matrix_r(car_data->motion, delta, car_data->prev_rot, &car->rot);
            qcopy(car_data->prev_pos, &car->pos);
            qcopy(car_data->prev_rot, &car->rot);
            id = car_data->iC0;
        } while (id != -1);
        FastVecSub_r(dp, &moby->pos, old_pos);
        update_entity_matrix_r(motion, dp, old_rot, &moby->rot);
    } else {
        STUB_printf_r(kerwan_train_motion_error_msg_r, data->iB8);
        DeleteMoby_r(moby);
        return;
    }
    *(unsigned short *)(kerwan_mobys_t + (data->iC4 << 8) + 0x34) |= 6;
}
