/* Builds two scaled offset vectors from the moby's matrix and adds them to out. */
void add_moby_rotation_based_offsets(char *moby, float *out) {
    float v[4];
    float a[4];
    float c[4];
    float d[4];
    float b[4];
    float m[16];
    struct SplineMobyVars *data;
    *(u128 *)v = 0;
    v[0] = 1.0f;
    data = (struct SplineMobyVars *)((Moby *)moby)->pvars;
    if (data->offset_a != 0.0f || data->offset_b != 0.0f) {
        euler_to_matrix(m, (float *)(moby + 0x40));
        transform_vector(a, v, m);
        *(u128 *)b = *(u128 *)a;
        b[2] = b[2] - 1.0f;
        FastVecCross(c, a, b);
        FastVecCross(d, a, c);
        FastVecScale(c, c, data->offset_a);
        FastVecScale(d, d, data->offset_b);
        FastVecAdd(out, out, c);
        FastVecAdd(out, out, d);
    }
}
